"""Analytical stationary mean and excess-variance ratio for the LINEAR bath-only model.

No third-party dependencies; k_B=1. This does not simulate the bouncing particle.
"""
from __future__ import annotations


def active_energy(omega: float, gamma: float, tau: float, sigma_force: float) -> float:
    """Mean extra modal energy generated by OU forcing."""
    if omega <= 0 or gamma <= 0 or tau <= 0 or sigma_force < 0:
        raise ValueError("Require positive omega, gamma, tau and nonnegative sigma_force")
    a = 1.0 / tau
    return sigma_force**2 * (gamma + a) / (
        2.0 * gamma * (omega**2 + 2.0 * gamma * a + a**2)
    )


def ratio(temperature: float, extra_energy: float) -> float:
    """Exact R for additive Gaussian active forcing plus thermal equilibrium."""
    if temperature <= 0 or extra_energy < 0:
        raise ValueError("Require positive temperature and nonnegative extra energy")
    return 1.0 + 2.0 * extra_energy / temperature


def main() -> None:
    temperature = 0.12
    tau, gamma, sigma_force = 0.65, 0.05, 0.30
    print("mode,omega,U0,mean_energy,R")
    for mode in range(1, 13):
        omega = float(mode)
        u0 = active_energy(omega, gamma, tau, sigma_force)
        print(f"{mode},{omega:.3f},{u0:.6f},{temperature+u0:.6f},{ratio(temperature,u0):.6f}")


if __name__ == "__main__":
    main()
